 * Uses a time-limited map implementation since Caffeine is not on the classpath.
 * expireAfterWrite = 1h, maximumSize = 10 000 entries.
 */
@Configuration
@EnableConfigurationProperties(PreviewProperties.class)
public class PreviewCacheConfig {

    @Bean(name = "previewCache")
    public TimedCache<String, PreviewResult> previewCache(PreviewProperties previewProperties) {
        int maxSize = previewProperties.cache().maxSize();
        long expireAfterWriteSeconds = previewProperties.cache().expireAfterWriteSeconds();
        return new TimedCache<>(maxSize, Duration.ofSeconds(expireAfterWriteSeconds));
    }
}
