package com.schwab.urlshortener.config;

import java.time.Duration;
import java.time.Instant;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

/**
 * A simple thread-safe in-process cache with TTL expiration and maximum size eviction.
 * Implemented with JDK standard library only (no Caffeine dependency).
 * Uses an LRU-style LinkedHashMap with write lock for eviction on insert.
 * TTL is enforced on read: expired entries are treated as absent and lazily removed.
 *
 * @param <K> key type
 * @param <V> value type
 */
public class TimedCache<K, V> {

    private final int maxSize;
    private final Duration ttl;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    private final LinkedHashMap<K, Entry<V>> store;

    public TimedCache(int maxSize, Duration ttl) {
        this.maxSize = maxSize;
        this.ttl = ttl;
        // Access-order LinkedHashMap for LRU eviction
        this.store = new LinkedHashMap<>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<K, Entry<V>> eldest) {
                return size() > maxSize;
            }
        };
    }

    /**
     * Returns the cached value if present and not expired, otherwise null.
     */
    public V get(K key) {
        lock.readLock().lock();
        try {
            Entry<V> entry = store.get(key);
            if (entry == null) {
                return null;
            }
            if (entry.isExpired()) {
                // Cannot remove under read lock; return null and let next write clean up
                return null;
            }
            return entry.value;
        } finally {
            lock.readLock().unlock();
        }
    }

    /**
     * Puts a value into the cache with the configured TTL.
     */
    public void put(K key, V value) {
        lock.writeLock().lock();
        try {
            store.put(key, new Entry<>(value, Instant.now().plus(ttl)));
        } finally {
            lock.writeLock().unlock();
        }
    }

    /**
     * Returns true if the key is present in the cache and not expired.
     */
    public boolean containsKey(K key) {
        return get(key) != null;
    }

    /**
     * Removes a key from the cache.
     */
    public void invalidate(K key) {
        lock.writeLock().lock();
        try {
            store.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    /**
     * Evicts all expired entries. Can be called periodically if desired.
     */
    public void evictExpired() {
        lock.writeLock().lock();
        try {
            store.entrySet().removeIf(e -> e.getValue().isExpired());
        } finally {
            lock.writeLock().unlock();
        }
    }

    private static final class Entry<V> {
        final V value;
        final Instant expiresAt;

        Entry(V value, Instant expiresAt) {
            this.value = value;
            this.expiresAt = expiresAt;
        }

        boolean isExpired() {
            return Instant.now().isAfter(expiresAt);
        }
    }
}
