package com.schwab.urlshortener.service;

import com.schwab.urlshortener.config.PreviewProperties;
import com.schwab.urlshortener.config.TimedCache;
import com.schwab.urlshortener.domain.PreviewResult;
import com.schwab.urlshortener.exception.SsrfBlockedException;
import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.URL;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;

/**
 * Orchestrates URL preview fetching: SSRF validation, HTTP GET, body cap,
 * redirect refusal, and HTML parsing (title + description meta tag).
 *
 * All exceptions on the fetch path are caught and mapped to PreviewResult.empty().
 * SsrfBlockedException is swallowed here and never propagates to GlobalExceptionHandler.
 */
@Service
public class UrlPreviewService {

    private static final Logger log = LoggerFactory.getLogger(UrlPreviewService.class);

    // Matches <title>...</title> (case-insensitive, non-greedy)
    private static final Pattern TITLE_PATTERN = Pattern.compile(
        "<title[^>]*>([^<]*)</title>",
        Pattern.CASE_INSENSITIVE | Pattern.DOTALL
    );

    // Matches <meta name="description" content="..."> in various attribute orderings
    private static final Pattern META_DESCRIPTION_PATTERN = Pattern.compile(
        "<meta[^>]+name=[\"']description[\"'][^>]+content=[\"']([^\"']*)[\"'][^>]*>|"
        + "<meta[^>]+content=[\"']([^\"']*)[\"'][^>]+name=[\"']description[\"'][^>]*>",
        Pattern.CASE_INSENSITIVE | Pattern.DOTALL
    );

    private final SsrfGuard ssrfGuard;
    private final HttpClient httpClient;
    private final TimedCache<String, PreviewResult> previewCache;
    private final int timeoutSeconds;
    private final int maxBodyBytes;

    public UrlPreviewService(
        SsrfGuard ssrfGuard,
        @Qualifier("previewHttpClient") HttpClient httpClient,
        @Qualifier("previewCache") TimedCache<String, PreviewResult> previewCache,
        PreviewProperties previewProperties
    ) {
        this.ssrfGuard = ssrfGuard;
        this.httpClient = httpClient;
        this.previewCache = previewCache;
        this.timeoutSeconds = previewProperties.http().timeoutSeconds();
        this.maxBodyBytes = previewProperties.http().maxBodyBytes();
    }

    /**
     * Fetches preview metadata for the given target URL.
     * Results are cached by shortCode.
     *
     * @param shortCode  cache key (the short code)
     * @param targetUrl  the resolved long URL to fetch
     * @return PreviewResult with title/description, or PreviewResult.empty() on any failure
     */
    public PreviewResult fetchPreview(String shortCode, String targetUrl) {
        // Check cache first
        PreviewResult cached = previewCache.get(shortCode);
        if (cached != null) {
            return cached;
        }

        PreviewResult result = doFetch(targetUrl);
        previewCache.put(shortCode, result);
        return result;
    }

    private PreviewResult doFetch(String targetUrl) {
        try {
            URL url = URI.create(targetUrl).toURL();

            // SSRF guard: validate IP ranges
            ssrfGuard.validate(url);

            HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(targetUrl))
                .timeout(Duration.ofSeconds(timeoutSeconds))
                .GET()
                .header("User-Agent", "UrlShortener-Preview/1.0")
                .header("Accept", "text/html,application/xhtml+xml")
                .build();

            HttpResponse<InputStream> response = httpClient.send(
                request,
                HttpResponse.BodyHandlers.ofInputStream()
            );

            // Refuse non-200 responses (including 3xx redirects)
            if (response.statusCode() != 200) {
                log.debug("Non-200 response {} for URL: {}", response.statusCode(), targetUrl);
                return PreviewResult.empty();
            }

            // Read at most maxBodyBytes
            byte[] bodyBytes;
            try (InputStream inputStream = response.body()) {
                bodyBytes = inputStream.readNBytes(maxBodyBytes);
            }

            // Detect charset from Content-Type header
            Charset charset = detectCharset(response);
            String html = new String(bodyBytes, charset);

            return parseHtml(html);

        } catch (SsrfBlockedException e) {
            log.debug("SSRF blocked for URL: {} - {}", targetUrl, e.getMessage());
            return PreviewResult.empty();
        } catch (java.net.http.HttpTimeoutException e) {
            log.debug("Timeout fetching URL: {}", targetUrl);
            return PreviewResult.empty();
        } catch (IOException e) {
            log.debug("IO error fetching URL: {} - {}", targetUrl, e.getMessage());
            return PreviewResult.empty();
        } catch (Exception e) {
            log.debug("Unexpected error fetching URL: {} - {}", targetUrl, e.getMessage());
            return PreviewResult.empty();
        }
    }

    private Charset detectCharset(HttpResponse<?> response) {
        return response.headers()
            .firstValue("Content-Type")
            .map(contentType -> {
                // Look for charset= in the Content-Type header
                int idx = contentType.toLowerCase().indexOf("charset=");
                if (idx >= 0) {
                    String charsetName = contentType.substring(idx + 8).trim();
                    // Remove any trailing parameters
                    int semicolon = charsetName.indexOf(';');
                    if (semicolon >= 0) {
                        charsetName = charsetName.substring(0, semicolon).trim();
                    }
                    // Remove quotes if present
                    charsetName = charsetName.replace("\"", "").replace("'", "").trim();
                    try {
                        return Charset.forName(charsetName);
                    } catch (Exception e) {
                        return StandardCharsets.UTF_8;
                    }
                }
                return StandardCharsets.UTF_8;
            })
            .orElse(StandardCharsets.UTF_8);
    }

    private PreviewResult parseHtml(String html) {
        String title = null;
        String description = null;

        Matcher titleMatcher = TITLE_PATTERN.matcher(html);
        if (titleMatcher.find()) {
            title = normalizeWhitespace(titleMatcher.group(1));
            if (title.isEmpty()) {
                title = null;
            }
        }

        Matcher metaMatcher = META_DESCRIPTION_PATTERN.matcher(html);
        if (metaMatcher.find()) {
            // Group 1 is from the name-first variant, group 2 from content-first
            String raw = metaMatcher.group(1) != null ? metaMatcher.group(1) : metaMatcher.group(2);
            description = normalizeWhitespace(raw);
            if (description.isEmpty()) {
                description = null;
            }
        }

        return PreviewResult.of(title, description);
    }

    private String normalizeWhitespace(String text) {
        if (text == null) {
            return "";
        }
        return text.trim().replaceAll("\\s+", " ");
    }
}
