package com.schwab.urlshortener.controller;

import com.schwab.urlshortener.domain.PreviewResponse;
import com.schwab.urlshortener.domain.PreviewResult;
import com.schwab.urlshortener.domain.Url;
import com.schwab.urlshortener.service.UrlPreviewService;
import com.schwab.urlshortener.service.UrlService;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST controller for the URL preview endpoint.
 * Kept separate from UrlApiController to eliminate path-variable ambiguity.
 *
 * GET /api/urls/{shortCode}/preview
 */
@RestController
@RequestMapping("/api/urls")
public class UrlPreviewController {

    private final UrlService urlService;
    private final UrlPreviewService urlPreviewService;

    public UrlPreviewController(UrlService urlService, UrlPreviewService urlPreviewService) {
        this.urlService = urlService;
        this.urlPreviewService = urlPreviewService;
    }

    /**
     * Resolves the short code and returns target-page metadata.
     *
     * @param shortCode the short code to resolve
     * @return PreviewResponse with shortCode, targetUrl, and optional title/description
     * @throws com.schwab.urlshortener.exception.UrlNotFoundException if the short code does not exist
     *         (propagated to GlobalExceptionHandler → 404)
     */
    @GetMapping("/{shortCode}/preview")
    public PreviewResponse getPreview(@PathVariable String shortCode) {
        // Resolve short code; throws UrlNotFoundException if not found (→ 404)
        Url url = urlService.findByShortCode(shortCode);
        String targetUrl = url.getLongUrl();

        // Fetch preview; never throws (all exceptions mapped to PreviewResult.empty())
        PreviewResult result = urlPreviewService.fetchPreview(shortCode, targetUrl);

        return new PreviewResponse(shortCode, targetUrl, result.getTitle(), result.getDescription());
    }
}
